<?php require __DIR__.'/bootstrap.php';$p=db();$d=body();switch(method()){case'GET':respond($p->query('SELECT * FROM sources ORDER BY active DESC,name')->fetchAll());case'POST':requireFields($d,['name','url']);if(!filter_var($d['url'],FILTER_VALIDATE_URL))fail('URL inválida');$p->prepare('INSERT INTO sources(name,type,url,active) VALUES(?,?,?,?)')->execute([clean($d['name']),clean($d['type']??'rss'),$d['url'],(int)($d['active']??1)]);respond(['id'=>insertedId($p,'sources')],201);case'PUT':requireFields($d,['id','name','url']);if(!filter_var($d['url'],FILTER_VALIDATE_URL))fail('URL inválida');$p->prepare('UPDATE sources SET name=?,type=?,url=?,active=? WHERE id=?')->execute([clean($d['name']),clean($d['type']),$d['url'],(int)$d['active'],(int)$d['id']]);respond(['updated'=>true]);case'DELETE':$p->prepare('DELETE FROM sources WHERE id=?')->execute([(int)$d['id']]);respond(['deleted'=>true]);default:fail('Método não permitido',405);}
